# ---- 写入 6 个语言文件 ----
for loc in LOCALES:
    path = os.path.join(BASE, f"{loc}.json")
    with open(path, "r", encoding="utf-8") as f:
        d = json.load(f)
    conv = d.setdefault("converter", {})
    n = 0
    for tid, langs in G.items():
        if loc not in langs:
            continue
        conv.setdefault(tid, {})["guide"] = langs[loc]
        n += 1
    with open(path, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print(f"{loc}: wrote {n} guides -> {path}")

print("DONE total tools:", len(G))
